def list_changed_paths(worktree: Path) -> list[Path]:
    porcelain = run_git(
        worktree, "status", "--porcelain=v1", "-z", "--untracked-files=all"
    )
    setup_output = read_setup_output(worktree)
    return [
        Path(entry[3:])
        for entry in split_null_terminated(porcelain)
        if len(entry) > 3 and not is_setup_output_entry(entry, setup_output)
    ]


def is_setup_output_entry(porcelain_entry: str, setup_output: frozenset[Path]) -> bool:
    return (
        porcelain_entry.startswith(UNTRACKED_STATUS)
        and Path(porcelain_entry[3:]) in setup_output
    )


def list_untracked_files(worktree: Path) -> list[Path]:
    setup_output = read_setup_output(worktree)
    return [
        untracked_file
        for untracked_file in list_untracked_files_with_setup_output(worktree)
        if untracked_file not in setup_output
    ]


def list_untracked_files_with_setup_output(worktree: Path) -> list[Path]:
    listing = run_git(worktree, "ls-files", "--others", "--exclude-standard", "-z")
    return [Path(entry) for entry in split_null_terminated(listing)]

def read_exclude_file(exclude_file: Path) -> str:
    if not exclude_file.is_file():
        return ""
    return exclude_file.read_text(encoding="utf-8")


def build_literal_exclude_pattern(path: Path) -> str:
    escaped = "".join(
        f"\\{character}" if character in PATTERN_SPECIAL_CHARACTERS else character
        for character in path.as_posix()
    )
    return f"/{escaped}"

